import 'package:flutter/material.dart';import 'package:supabase_flutter/supabase_flutter.dart';import '../theme/app_theme.dart';
class NotificationsScreen extends StatefulWidget{const NotificationsScreen({super.key});@override State<NotificationsScreen>createState()=>_N();}
class _N extends State<NotificationsScreen>{List<Map<String,dynamic>> rows=[];bool loading=true;Future<void>load()async{final u=Supabase.instance.client.auth.currentUser;if(u!=null){final r=await Supabase.instance.client.from('notifications').select().eq('user_id',u.id).order('created_at',ascending:false).limit(50);rows=List<Map<String,dynamic>>.from(r);}if(mounted)setState(()=>loading=false);}@override void initState(){super.initState();load();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Notifications')),body:loading?const Center(child:CircularProgressIndicator()):rows.isEmpty?const Center(child:Text('No new notifications')):ListView(padding:const EdgeInsets.all(18),children:rows.map((x)=>Card(child:ListTile(leading:const CircleAvatar(backgroundColor:AppTheme.green,child:Icon(Icons.notifications,color:Colors.black)),title:Text('${x['title']??''}'),subtitle:Text('${x['body']??''}\n${x['created_at']??''}')))).toList()));}
